def sigmoid(value):
    return 1 / (1 + np.exp(-value))

def gru_step(signal, previous, update_override=None):
    reset = sigmoid(signal - previous)
    update = sigmoid(signal + previous)
    if update_override is not None:
        update = float(update_override)
    candidate = np.tanh(signal + 0.8 * reset * previous)
    state = (1 - update) * previous + update * candidate
    return state, reset, update, candidate

state, reset, update, candidate = gru_step(1., 0.)
assert 0 < reset < 1 and 0 < update < 1
print('Новый сигнал:', round(state, 3))
